head.script:
// 테스트 설명, 유효성 값 설정
scwin.tData = {
    "description" : "[gridView > M > headerMergeClear]<br/>headerMerge() 메소드로 동적 병합된 Header Column 을 모두 해제합니다.",
    "validation" : [
        "headerMerge() 메소드로 동적 병합된 Header Column 을 모두 해제합니다."
    ]
}



scwin.onpageload = function () {
    // Global DataList 생성 호출
    $c.gcm.createCommonDatalist();

    // comp 초기 생성
    scwin.comp_init();

    // 테스트 설명, 유효성 생성
    wf_body_left.getObj("scwin").createValidation(scwin.tData);
};



// comp 생성
scwin.comp_init = async function () {
    // 기존 target 있으면 삭제
    if (typeof target1 !== 'undefined') {
        target1.remove();
    }

    // 안내 라벨 생성 (가장 먼저)
    $c.gcm.createLabel('label="Header Column 은 column1 ~ column6 이며 디자인 병합이 없는 평범한 헤더입니다. headerMerge 로 만든 여러 동적 병합 영역을 headerMergeClear 로 한 번에 모두 해제할 수 있습니다."', '', 'label1');

    // 기존 dataList 있으면 삭제
    if (typeof dlt_bind !== 'undefined') {
        $p.data.remove("dlt_bind");
    }

    // grp_comp 영역 / 네임스페이스 확인
    let grp_comp = $c.gcm.getTestGroup();
    let strNameSpace = $c.gcm.getNameSpace();

    // DataList 생성 (col1~col6) 후 데이터 4행 setJSON 으로 채우고 gridView 에 바인딩
    let strData = '';
    strData += '<w2:dataList ' + strNameSpace + ' id="dlt_bind" baseNode="list" repeatNode="map">';
    strData += '<w2:columnInfo>';
    for (let c = 1; c <= 6; c++) {
        strData += '<w2:column id="col' + c + '" name="name' + c + '" dataType="text"></w2:column>';
    }
    strData += '</w2:columnInfo>';
    strData += '<w2:data use="true"></w2:data>';
    strData += '</w2:dataList>';
    $p.data.create(strData);

    let jsonData = [];
    for (let rIdx = 1; rIdx <= 4; rIdx++) {
        jsonData.push({ col1: "v" + rIdx + "_1", col2: "v" + rIdx + "_2", col3: "v" + rIdx + "_3", col4: "v" + rIdx + "_4", col5: "v" + rIdx + "_5", col6: "v" + rIdx + "_6" });
    }
    dlt_bind.setJSON(jsonData);

    // Header Column 6개(column1~column6) + Body 6컬럼 동적 생성 (디자인 병합 없음)
    let strTarget = '';
    strTarget += '<w2:gridView ' + strNameSpace + ' checkAllType="false" dataList="data:dlt_bind" id="" style="width:600px;height:260px;">';
    strTarget += '<w2:header style="" id="header1">';
    strTarget += '<w2:row style="" id="row1">';
    strTarget += '<w2:column width="90" inputType="text" id="column1" value="name1"></w2:column>';
    strTarget += '<w2:column width="90" inputType="text" id="column2" value="name2"></w2:column>';
    strTarget += '<w2:column width="90" inputType="text" id="column3" value="name3"></w2:column>';
    strTarget += '<w2:column width="90" inputType="text" id="column4" value="name4"></w2:column>';
    strTarget += '<w2:column width="90" inputType="text" id="column5" value="name5"></w2:column>';
    strTarget += '<w2:column width="90" inputType="text" id="column6" value="name6"></w2:column>';
    strTarget += '</w2:row>';
    strTarget += '</w2:header>';
    strTarget += '<w2:gBody style="" id="gBody1">';
    strTarget += '<w2:row style="" id="row2">';
    strTarget += '<w2:column width="90" inputType="text" id="col1" value=""></w2:column>';
    strTarget += '<w2:column width="90" inputType="text" id="col2" value=""></w2:column>';
    strTarget += '<w2:column width="90" inputType="text" id="col3" value=""></w2:column>';
    strTarget += '<w2:column width="90" inputType="text" id="col4" value=""></w2:column>';
    strTarget += '<w2:column width="90" inputType="text" id="col5" value=""></w2:column>';
    strTarget += '<w2:column width="90" inputType="text" id="col6" value=""></w2:column>';
    strTarget += '</w2:row>';
    strTarget += '</w2:gBody>';
    strTarget += '</w2:gridView>';

    scwin.target1 = await $p.dynamicCreate("target1", "gridView", strTarget, grp_comp);
}



// 화면 표시 Header th 개수 / 특정 Header colspan 반환 (간단 확인용)
scwin.getVisibleThCount = function () {
    let cnt = 0;
    let allTh = document.querySelectorAll("th[data-header_id], th[header_id]");
    for (let i = 0; i < allTh.length; i++) {
        if (allTh[i].style.display !== "none") cnt++;
    }
    return cnt;
}

scwin.getHeaderColspan = function (headerID) {
    let th = document.querySelector("th[data-header_id='" + headerID + "'], th[header_id='" + headerID + "']");
    return th ? (th.getAttribute("colspan") || "없음") : "없음";
}



// (사전조건) headerMerge 로 여러 동적 병합 영역 생성 — clear 의 '전체 해제' 효과 확인용
scwin.btn_headerMerge_onclick = function () {
    target1.headerMergeClear();
    target1.headerMerge("column1", "column2");
    target1.headerMerge("column4", "column5");
    wf_body_bottom.getObj("scwin").setReturnValue("동적 병합(column1~2, column4~5) → 화면 th " + scwin.getVisibleThCount() + "개 (column1 colspan=" + scwin.getHeaderColspan("column1") + ", column4 colspan=" + scwin.getHeaderColspan("column4") + ")");
}



// (validation #2) headerMergeClear 실행 — 동적 병합된 Header Column 을 모두 해제
scwin.btn_headerMergeClear_onclick = function () {
    let result = target1.headerMergeClear();
    wf_body_bottom.getObj("scwin").setReturnValue("headerMergeClear() : " + result + " → 화면 th " + scwin.getVisibleThCount() + "개 (column1 colspan=" + scwin.getHeaderColspan("column1") + ", column4 colspan=" + scwin.getHeaderColspan("column4") + ")");
}
